#!/bin/sh
# Build stock.txt from the day's movements log: one "SKU-# net" line per SKU.
# A SKU is reported even when its receipts and issues cancel out.
awk '
    { seen[$1] = 1; net[$1] += ($2 == "receipt" ? $3 : -$3) }
    END {
        # SKU-9 is a catalog SKU and must be included even on a quiet day.
        seen["SKU-9"] = 1
        for (sku in seen) print sku, net[sku] + 0
    }
' movements.log | sort > stock.txt
